/// <summary>
/// zusätzlich zum Record in smmActivityParentLinkTable ist ein Record in KCS_KBVBuildingProjectTable notwendig
/// </summary>
/// <param name="sender">smmActivityParentLinkTable</param>
/// <param name="e">DataEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    DataEventHandler(tableStr(smmActivityParentLinkTable), DataEventType::Inserted)]
public static void smmActivityParentLinkTable_onInserted(Common sender, DataEventArgs e)
{
    smmActivityParentLinkTable  parentLinkTable = sender;
    KCS_KBVBuildingProjectTable buildingProjectTable;

    if (parentLinkTable.ParentType == smmActivityParentType::BuildingProject)
    {
        buildingProjectTable = KCS_KBVBuildingProjectTable::findByRecId(parentLinkTable.RefRecId);
        if (buildingProjectTable.KCS_KBVBuildingProjectID)
        {
            if (!KCS_KBVActivitiesForBP::exist(buildingProjectTable.KCS_KBVBuildingProjectID, parentLinkTable.ActivityNumber))
            {
                KCS_KBVActivitiesForBP::createReference(buildingProjectTable.KCS_KBVBuildingProjectID, parentLinkTable.ActivityNumber, curExt());
            }
        }
    }
}
